package com.rooftopguide;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import net.runelite.api.Client;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The dark cover used by transparent mode, with the highlights, timer bar and the game's click cross redrawn on top.
 * There are two of these: one above everything, which also hides the interface, and one under the interface panels,
 * used to leave the interface visible (e.g. to teleport after a lap) while the game stays dark.
 */
abstract class FocusCover extends Overlay
{
	/** The game's click animation: 4 frames, in the CROSS sprite group (yellow frames 0-3, red frames 4-7). */
	private static final int CROSS_FRAMES = 4;
	private static final int RED_FRAME_OFFSET = 4;
	private static final long CROSS_MILLIS = 450;

	private final Client client;
	private final RooftopGuidePlugin plugin;
	private final RooftopGuideConfig config;
	private final SpriteManager spriteManager;
	private final RooftopGuideOverlay obstacleOverlay;
	private final MarkOverlay markOverlay;
	private final ObstacleTimerOverlay timerOverlay;

	FocusCover(Client client, RooftopGuidePlugin plugin, RooftopGuideConfig config, SpriteManager spriteManager,
		RooftopGuideOverlay obstacleOverlay, MarkOverlay markOverlay, ObstacleTimerOverlay timerOverlay,
		OverlayLayer layer)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.spriteManager = spriteManager;
		this.obstacleOverlay = obstacleOverlay;
		this.markOverlay = markOverlay;
		this.timerOverlay = timerOverlay;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(layer);
	}

	/** @return true if this cover is the one that should be drawing right now */
	abstract boolean isActive(RooftopGuidePlugin plugin);

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!isActive(plugin))
		{
			return null;
		}

		int alpha = Math.round(255 * config.focusDarkness() / 100f);
		graphics.setColor(new Color(0, 0, 0, alpha));
		graphics.fillRect(0, 0, client.getCanvasWidth(), client.getCanvasHeight());

		markOverlay.renderHighlights(graphics);
		obstacleOverlay.renderHighlights(graphics);
		timerOverlay.renderOnCover(graphics);
		drawClickCross(graphics);
		return null;
	}

	/** Draws the game's own click-cross frames over the cover, since the cover hides the one the game draws. */
	private void drawClickCross(Graphics2D graphics)
	{
		long age = System.currentTimeMillis() - plugin.getClickTimeMillis();
		if (plugin.getClickX() < 0 || age < 0 || age >= CROSS_MILLIS)
		{
			return;
		}

		int frame = (int) (age * CROSS_FRAMES / CROSS_MILLIS) + (plugin.isClickInteraction() ? RED_FRAME_OFFSET : 0);
		BufferedImage sprite = spriteManager.getSprite(SpriteID.CROSS, frame);
		if (sprite != null)
		{
			graphics.drawImage(sprite,
				plugin.getClickX() - sprite.getWidth() / 2, plugin.getClickY() - sprite.getHeight() / 2, null);
		}
	}
}

package com.rooftopguide;

import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.overlay.OverlayLayer;

/** The cover above everything, interface included. Active in transparent mode unless the interface is revealed. */
class FocusOverlay extends FocusCover
{
	@Inject
	private FocusOverlay(Client client, RooftopGuidePlugin plugin, RooftopGuideConfig config,
		SpriteManager spriteManager, RooftopGuideOverlay obstacleOverlay, MarkOverlay markOverlay,
		ObstacleTimerOverlay timerOverlay)
	{
		super(client, plugin, config, spriteManager, obstacleOverlay, markOverlay, timerOverlay,
			OverlayLayer.ALWAYS_ON_TOP);
	}

	@Override
	boolean isActive(RooftopGuidePlugin plugin)
	{
		return plugin.isCoverOverInterface();
	}
}

package com.rooftopguide;

import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.overlay.OverlayLayer;

/**
 * The cover under the interface panels. Active in transparent mode while the interface is revealed: the game stays
 * dark and see-through, but the inventory, spellbook, chat and the rest draw normally on top of it.
 */
class FocusUnderlay extends FocusCover
{
	@Inject
	private FocusUnderlay(Client client, RooftopGuidePlugin plugin, RooftopGuideConfig config,
		SpriteManager spriteManager, RooftopGuideOverlay obstacleOverlay, MarkOverlay markOverlay,
		ObstacleTimerOverlay timerOverlay)
	{
		super(client, plugin, config, spriteManager, obstacleOverlay, markOverlay, timerOverlay,
			OverlayLayer.UNDER_WIDGETS);
	}

	@Override
	boolean isActive(RooftopGuidePlugin plugin)
	{
		return plugin.isCoverUnderInterface();
	}
}

package com.rooftopguide;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Marks of grace on the player's roof level: a softly pulsing tile, a light beam rising from it, and the mark's own
 * icon floating at the top of the beam, so they stand out from a distance without cluttering the screen.
 */
@Singleton
class MarkOverlay extends Overlay
{
	/** Item ID of a mark of grace, used to draw its icon. */
	static final int MARK_OF_GRACE = 11849;

	private static final int BEAM_HEIGHT = 70;
	private static final double PULSE_MILLIS = 900;

	private final Client client;
	private final RooftopGuidePlugin plugin;
	private final RooftopGuideConfig config;
	private final ItemManager itemManager;
	private final MarkReach reach;

	@Inject
	private MarkOverlay(Client client, RooftopGuidePlugin plugin, RooftopGuideConfig config, ItemManager itemManager,
		MarkReach reach)
	{
		this.reach = reach;
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		// in transparent mode the FocusOverlay draws these above everything else
		if (!plugin.isFocusMode())
		{
			renderHighlights(graphics);
		}
		return null;
	}

	/** A mark on the player's level that the player can walk to from where they stand. */
	private boolean isVisible(Tile tile, int plane)
	{
		return tile.getPlane() == plane && tile.getLocalLocation() != null
			&& reach.canReach(tile);
	}

	/** @return how many marks of grace are lying anywhere nearby, on any roof or level, counting stacks */
	int countMarks()
	{
		int count = 0;
		for (TileItem mark : plugin.getMarks().keySet())
		{
			count += Math.max(1, mark.getQuantity());
		}
		return count;
	}

	void renderHighlights(Graphics2D graphics)
	{
		Player player = client.getLocalPlayer();
		if (!config.showMarks() || player == null)
		{
			return;
		}

		int plane = player.getWorldLocation().getPlane();
		double pulse = 0.5 + 0.5 * Math.sin(2 * Math.PI * (System.currentTimeMillis() % (long) PULSE_MILLIS) / PULSE_MILLIS);
		BufferedImage icon = itemManager.getImage(MARK_OF_GRACE);
		Color color = config.markColor();

		for (Tile tile : plugin.getMarks().values())
		{
			if (!isVisible(tile, plane))
			{
				continue;
			}

			Polygon outline = Perspective.getCanvasTilePoly(client, tile.getLocalLocation());
			if (outline == null)
			{
				continue;
			}

			// pulsing glow on the tile, with a crisp edge
			graphics.setColor(withAlpha(color, (int) (50 + 90 * pulse)));
			graphics.fill(outline);
			graphics.setColor(withAlpha(color, 230));
			graphics.setStroke(new BasicStroke(2));
			graphics.draw(outline);

			Point base = Perspective.localToCanvas(client, tile.getLocalLocation(), tile.getPlane());
			if (base == null)
			{
				continue;
			}

			// light beam fading upward, then the icon bobbing at the top
			graphics.setPaint(new GradientPaint(
				base.getX(), base.getY(), withAlpha(color, 170),
				base.getX(), base.getY() - BEAM_HEIGHT, withAlpha(color, 0)));
			graphics.setStroke(new BasicStroke(3));
			graphics.drawLine(base.getX(), base.getY(), base.getX(), base.getY() - BEAM_HEIGHT);

			if (icon != null)
			{
				int bob = (int) Math.round(3 * pulse);
				graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, (float) (0.75 + 0.25 * pulse)));
				graphics.drawImage(icon,
					base.getX() - icon.getWidth() / 2, base.getY() - BEAM_HEIGHT - icon.getHeight() - bob, null);
				graphics.setComposite(AlphaComposite.SrcOver);
			}
		}
	}

	private static Color withAlpha(Color color, int alpha)
	{
		return new Color(color.getRed(), color.getGreen(), color.getBlue(), Math.max(0, Math.min(255, alpha)));
	}
}

package com.rooftopguide;

import java.util.ArrayDeque;
import java.util.Arrays;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.CollisionData;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.Constants;
import net.runelite.api.Player;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

/**
 * Works out which tiles the player can walk to from where they stand, using the game's own collision data. A mark of
 * grace on another roof (or across a gap or fence) isn't reachable, so it can't be picked up from here.
 */
@Singleton
class MarkReach
{
	private static final int SIZE = Constants.SCENE_SIZE;
	private static final int BLOCKED = CollisionDataFlag.BLOCK_MOVEMENT_FULL
		| CollisionDataFlag.BLOCK_MOVEMENT_OBJECT
		| CollisionDataFlag.BLOCK_MOVEMENT_FLOOR
		| CollisionDataFlag.BLOCK_MOVEMENT_FLOOR_DECORATION;

	private final Client client;

	private final boolean[][] reachable = new boolean[SIZE][SIZE];
	private final ArrayDeque<int[]> queue = new ArrayDeque<>();
	// what the cached result was computed for; it is redone when the player steps, or the map or level changes
	private int cachedX = -1;
	private int cachedY = -1;
	private int cachedPlane = -1;
	private int cachedBaseX = -1;
	private int cachedBaseY = -1;

	@Inject
	private MarkReach(Client client)
	{
		this.client = client;
	}

	/** @return true if the tile is on the player's level and connected to the player's tile by walkable ground */
	boolean canReach(Tile tile)
	{
		Player player = client.getLocalPlayer();
		WorldView worldView = client.getTopLevelWorldView();
		CollisionData[] maps = worldView == null ? null : worldView.getCollisionMaps();
		int plane = worldView == null ? -1 : worldView.getPlane();
		if (player == null || maps == null || plane < 0 || tile.getPlane() != plane || maps[plane] == null)
		{
			return false;
		}

		int[][] flags = maps[plane].getFlags();
		LocalPoint here = player.getLocalLocation();
		int x = here.getSceneX();
		int y = here.getSceneY();
		if (x != cachedX || y != cachedY || plane != cachedPlane
			|| worldView.getBaseX() != cachedBaseX || worldView.getBaseY() != cachedBaseY)
		{
			flood(flags, x, y);
			cachedX = x;
			cachedY = y;
			cachedPlane = plane;
			cachedBaseX = worldView.getBaseX();
			cachedBaseY = worldView.getBaseY();
		}

		net.runelite.api.Point target = tile.getSceneLocation();
		int tx = target.getX();
		int ty = target.getY();
		return inScene(tx, ty) && (reachable[tx][ty] || touchesReachable(tx, ty));
	}

	/** The mark's own tile may be flagged blocked (it can sit against an obstacle), so a reached neighbour is enough. */
	private boolean touchesReachable(int x, int y)
	{
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				if (inScene(x + dx, y + dy) && reachable[x + dx][y + dy])
				{
					return true;
				}
			}
		}
		return false;
	}

	private void flood(int[][] flags, int startX, int startY)
	{
		for (boolean[] column : reachable)
		{
			Arrays.fill(column, false);
		}
		queue.clear();
		if (!inScene(startX, startY))
		{
			return;
		}

		reachable[startX][startY] = true;
		queue.add(new int[]{startX, startY});
		while (!queue.isEmpty())
		{
			int[] at = queue.poll();
			for (int dx = -1; dx <= 1; dx++)
			{
				for (int dy = -1; dy <= 1; dy++)
				{
					int nx = at[0] + dx;
					int ny = at[1] + dy;
					if ((dx != 0 || dy != 0) && inScene(nx, ny) && !reachable[nx][ny]
						&& canStep(flags, at[0], at[1], dx, dy))
					{
						reachable[nx][ny] = true;
						queue.add(new int[]{nx, ny});
					}
				}
			}
		}
	}

	/** A step needs a walkable tile with no wall in the way; a diagonal also needs both tiles it cuts past. */
	private static boolean canStep(int[][] flags, int x, int y, int dx, int dy)
	{
		if (dx != 0 && dy != 0)
		{
			return canStep(flags, x, y, dx, 0) && canStep(flags, x, y, 0, dy)
				&& canStep(flags, x + dx, y, 0, dy) && canStep(flags, x, y + dy, dx, 0);
		}

		int nx = x + dx;
		int ny = y + dy;
		if (!inScene(nx, ny) || (flags[nx][ny] & BLOCKED) != 0)
		{
			return false;
		}
		int leaving = dy > 0 ? CollisionDataFlag.BLOCK_MOVEMENT_NORTH
			: dy < 0 ? CollisionDataFlag.BLOCK_MOVEMENT_SOUTH
			: dx > 0 ? CollisionDataFlag.BLOCK_MOVEMENT_EAST : CollisionDataFlag.BLOCK_MOVEMENT_WEST;
		int entering = dy > 0 ? CollisionDataFlag.BLOCK_MOVEMENT_SOUTH
			: dy < 0 ? CollisionDataFlag.BLOCK_MOVEMENT_NORTH
			: dx > 0 ? CollisionDataFlag.BLOCK_MOVEMENT_WEST : CollisionDataFlag.BLOCK_MOVEMENT_EAST;
		return (flags[x][y] & leaving) == 0 && (flags[nx][ny] & entering) == 0;
	}

	private static boolean inScene(int x, int y)
	{
		return x >= 0 && x < SIZE && y >= 0 && y < SIZE;
	}
}

package com.rooftopguide;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A bar while an obstacle is being crossed, filling toward how long that obstacle usually takes (averaged from earlier
 * laps). Handy on the long obstacles, to know when to look. Hold Alt to drag it, or drag its edges to resize it.
 * A mark of grace icon hangs under its left end, with a count, while any marks are lying nearby, on any roof.
 */
@Singleton
class ObstacleTimerOverlay extends Overlay
{
	private static final Dimension DEFAULT_SIZE = new Dimension(240, 16);
	private static final int MAX_ARC = 14;
	private static final int MIN_ICON_HEIGHT = 16;
	private static final int MAX_ICON_HEIGHT = 32;

	private final Client client;
	private final RooftopGuidePlugin plugin;
	private final RooftopGuideConfig config;
	private final MarkOverlay markOverlay;
	private final ItemManager itemManager;

	@Inject
	private ObstacleTimerOverlay(Client client, RooftopGuidePlugin plugin, RooftopGuideConfig config,
		MarkOverlay markOverlay, ItemManager itemManager)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.markOverlay = markOverlay;
		this.itemManager = itemManager;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		// Alt-drag on the edges resizes it; the size is kept by RuneLite and "Reset" in its menu restores the default
		setResizable(true);
		setMinimumSize(4);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		boolean bar = isShown();
		int marks = markCount();
		// while Alt is held an empty bar shows so there is something to grab, even between obstacles
		boolean placeholder = !bar && marks == 0 && client.isKeyPressed(KeyCode.KC_ALT);
		if (!bar && marks == 0 && !placeholder)
		{
			return null;
		}
		Dimension size = getPreferredSize() != null ? getPreferredSize() : DEFAULT_SIZE;
		// in transparent mode the FocusOverlay draws this above the cover, at this overlay's current spot; returning
		// the size either way keeps the bounds current so it can still be dragged
		if (!plugin.isFocusMode())
		{
			draw(graphics, size, bar, placeholder, marks);
		}
		return size;
	}

	/** Called by the transparent mode cover to draw this above it, where the user has put it. */
	void renderOnCover(Graphics2D graphics)
	{
		boolean bar = isShown();
		int marks = markCount();
		boolean placeholder = !bar && marks == 0 && client.isKeyPressed(KeyCode.KC_ALT);
		Rectangle bounds = getBounds();
		if ((!bar && marks == 0 && !placeholder) || bounds == null || bounds.isEmpty())
		{
			return;
		}
		graphics.translate(bounds.x, bounds.y);
		draw(graphics, bounds.getSize(), bar, placeholder, marks);
		graphics.translate(-bounds.x, -bounds.y);
	}

	private int markCount()
	{
		return config.showMarkBadge() ? markOverlay.countMarks() : 0;
	}

	// the bar shows after the XP drop too, full and green, for the moment the character is free to move on
	private boolean isShown()
	{
		return isRunning() || (config.showCrossingTimer() && plugin.isReadyForNext());
	}

	// the bar only runs for an uninterrupted click straight to the obstacle
	private boolean isRunning()
	{
		return config.showCrossingTimer() && plugin.getPendingId() != -1 && !plugin.isPendingInterrupted();
	}

	private void draw(Graphics2D graphics, Dimension size, boolean bar, boolean placeholder, int marks)
	{
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		if (bar || placeholder)
		{
			drawBar(graphics, size, placeholder);
		}
		if (marks > 0)
		{
			drawMarkBadge(graphics, size, marks);
		}
	}

	private void drawBar(Graphics2D graphics, Dimension size, boolean placeholder)
	{
		int width = size.width;
		int height = size.height;
		int arc = Math.min(MAX_ARC, height);
		Color fill = config.inProgressColor();
		double fraction = 0;
		if (!placeholder && !isRunning())
		{
			// ready: the XP drop landed
			fraction = 1;
			fill = config.highlightColor();
		}
		else if (!placeholder)
		{
			long elapsed = plugin.getPendingElapsedMillis();
			Long expected = plugin.getPendingExpectedMillis();

			// the bar stays empty until this obstacle has been completed once
			fraction = expected == null ? 0 : Math.min(1.0, elapsed / (double) expected);
			if (expected != null && elapsed >= expected - config.timerWarnSeconds() * 1000L)
			{
				fill = config.highlightColor();
			}
		}

		Shape shape = new RoundRectangle2D.Float(0.5f, 0.5f, width - 1f, height - 1f, arc, arc);
		int background = Math.round(config.timerBackground() * 2.55f);

		// soft drop shadow so the bar lifts off any scenery behind it
		graphics.setColor(new Color(0, 0, 0, 70));
		graphics.fill(new RoundRectangle2D.Float(0.5f, 2f, width - 1f, height - 1f, arc, arc));

		// dark glass track, a touch lighter at the top
		graphics.setPaint(new GradientPaint(0, 0, new Color(34, 40, 52, background),
			0, height, new Color(12, 15, 20, background)));
		graphics.fill(shape);

		// the fill, clipped to the bar's shape so both ends stay rounded
		int fillWidth = (int) Math.round(width * fraction);
		if (fillWidth > 0)
		{
			Shape oldClip = graphics.getClip();
			graphics.clip(shape);

			graphics.setPaint(new GradientPaint(0, 0, shade(fill, 1.25f, 235), 0, height, shade(fill, 0.72f, 235)));
			graphics.fillRect(0, 0, fillWidth, height);

			// glossy highlight across the top half
			graphics.setPaint(new GradientPaint(0, 0, new Color(255, 255, 255, 70),
				0, height / 2f, new Color(255, 255, 255, 0)));
			graphics.fillRect(0, 0, fillWidth, Math.max(1, height / 2));

			// a bright edge where the bar has got to
			if (fraction < 1)
			{
				graphics.setColor(new Color(255, 255, 255, 150));
				graphics.fillRect(Math.max(0, fillWidth - 2), 0, 2, height);
			}
			graphics.setClip(oldClip);
		}

		// crisp border in the bar's color, with a faint inner line
		graphics.setStroke(new BasicStroke(1.5f));
		graphics.setColor(new Color(fill.getRed(), fill.getGreen(), fill.getBlue(), 230));
		graphics.draw(shape);
		if (height >= 10)
		{
			graphics.setStroke(new BasicStroke(1f));
			graphics.setColor(new Color(255, 255, 255, 35));
			graphics.draw(new RoundRectangle2D.Float(2f, 2f, width - 4f, height - 4f,
				Math.max(0, arc - 3), Math.max(0, arc - 3)));
		}
	}

	/**
	 * The mark of grace icon with "x2", "x3"... beside it when there is more than one, hanging just under the bar's
	 * left end. No box around it: the icon and text scale with the bar, within limits that keep them readable.
	 */
	private void drawMarkBadge(Graphics2D graphics, Dimension size, int marks)
	{
		BufferedImage icon = itemManager.getImage(MarkOverlay.MARK_OF_GRACE);
		int iconHeight = Math.max(MIN_ICON_HEIGHT, Math.min(MAX_ICON_HEIGHT, Math.round(size.height * 0.6f)));
		// item icons are a little wider than tall; keep their proportions
		int iconWidth = icon == null ? iconHeight : Math.round(iconHeight * icon.getWidth() / (float) icon.getHeight());

		int x = 2;
		int y = size.height + 2;
		if (icon != null)
		{
			// a soft shadow under the icon so it reads over any scenery
			graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.45f));
			graphics.drawImage(icon, x + 1, y + 1, iconWidth, iconHeight, null);
			graphics.setComposite(AlphaComposite.SrcOver);
			graphics.drawImage(icon, x, y, iconWidth, iconHeight, null);
		}

		if (marks > 1)
		{
			graphics.setFont(graphics.getFont().deriveFont(Font.BOLD, Math.max(11f, iconHeight * 0.6f)));
			FontMetrics metrics = graphics.getFontMetrics();
			int textX = x + iconWidth + 4;
			int baseline = y + (iconHeight + metrics.getAscent() - metrics.getDescent()) / 2;
			String text = "x" + marks;
			graphics.setColor(new Color(0, 0, 0, 210));
			graphics.drawString(text, textX + 1, baseline + 1);
			graphics.setColor(Color.WHITE);
			graphics.drawString(text, textX, baseline);
		}
	}

	/** The color lightened (factor above 1) or darkened (below 1), with the given alpha. */
	private static Color shade(Color color, float factor, int alpha)
	{
		return new Color(
			Math.min(255, Math.round(color.getRed() * factor)),
			Math.min(255, Math.round(color.getGreen() * factor)),
			Math.min(255, Math.round(color.getBlue() * factor)),
			alpha);
	}
}

